




"use strict";





const splitIntoLines = (str) => {
	const results = [];
	const len = str.length;
	let i = 0;
	while (i < len) {
		
		
		const n = str.indexOf("\n", i);
		if (n === -1) {
			results.push(i === 0 ? str : str.slice(i));
			break;
		}
		if (n === i) {
			results.push("\n");
		} else {
			results.push(str.slice(i, n + 1));
		}
		i = n + 1;
	}
	return results;
};

module.exports = splitIntoLines;
